import { Router } from "express";
import { issueToken, verifyToken } from "../auth/tokens";

const router = Router();

router.post("/session", (req, res) => {
  const { userId, password } = req.body ?? {};
  if (!userId || !password) return res.status(400).json({ error: "missing_credentials" });
  res.json({ token: issueToken(userId) });
});

router.post("/session/refresh", (req, res) => {
  const token = String(req.header("authorization") ?? "").replace("Bearer ", "");
  const payload = verifyToken(token);
  if (!payload) return res.status(401).json({ error: "invalid_token" });
  res.json({ token: issueToken(payload.sub) });
});

export default router;

