import { useEffect } from "react";
import { refresh } from "./session";

// Refresh the access token every 10 minutes while the app is open.
export function useAutoRefresh() {
  useEffect(() => {
    const id = setInterval(() => {
      refresh();
    }, 10 * 60 * 1000);
  }, []);
}

